    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 _value) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(supplyBefore >= _value);
        c.burn(_value); if (__ESBMC_reverted()) return;
        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        assert(supplyAfter == supplyBefore - _value);
    }
}

